"""Modern self-contained HTML explorer for ledger snapshot data."""

# ruff: noqa: E501 -- embedded HTML, CSS, and JavaScript stay together for portability.

from __future__ import annotations

import json
from typing import Any

TEMPLATE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src https: data:; connect-src 'none'; font-src 'none'">
<title>Epiq data explorer</title><style>
:root{--bg:#f6f7f8;--surface:#fff;--surface2:#f1f3f5;--text:#17191c;--muted:#687078;--line:#dfe3e6;--accent:#146c5a;--accent2:#e7f3ef;--warn:#fff2c7;--blue:#eaf2f8;--mono:ui-monospace,SFMono-Regular,Menlo,monospace;--sans:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 var(--sans)}button,input{font:inherit}.appbar{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:18px 24px;background:var(--surface);border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:14px;min-width:0}.mark{display:grid;place-items:center;width:36px;height:36px;border-radius:9px;background:#17211f;color:#fff;font-weight:750;letter-spacing:-.04em}.brand h1{margin:0;font-size:18px;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.brand p{margin:3px 0 0;color:var(--muted);font-size:12px}.snapshot{flex:none;padding:6px 9px;border-radius:999px;background:var(--accent2);color:var(--accent);font-size:12px;font-weight:650}.tabs{display:flex;gap:4px;padding:0 20px;background:var(--surface);border-bottom:1px solid var(--line);overflow:auto}.tabs button{border:0;border-bottom:2px solid transparent;background:transparent;padding:12px 10px;color:var(--muted);cursor:pointer;white-space:nowrap}.tabs button.active{border-bottom-color:var(--accent);color:var(--text);font-weight:650}.view{display:none}.view.active{display:block}.data-layout{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:calc(100vh - 108px)}.table-nav{padding:18px 12px;background:var(--surface);border-right:1px solid var(--line)}.section-label{padding:0 10px 8px;color:var(--muted);font:650 11px/1.4 var(--mono);letter-spacing:.06em;text-transform:uppercase}.table-nav button{display:block;width:100%;border:0;border-radius:7px;background:transparent;padding:9px 10px;text-align:left;cursor:pointer}.table-nav button:hover{background:var(--surface2)}.table-nav button.active{background:var(--accent2);color:#0d5648;font-weight:650}.table-nav small{display:block;margin-top:2px;color:var(--muted);font-weight:400}.content{min-width:0;padding:20px 22px 48px}.content-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:14px}.content-head h2{margin:0;font-size:20px}.meta{color:var(--muted);font:600 11px/1.4 var(--mono);letter-spacing:.04em;text-transform:uppercase}.toolbar{display:flex;gap:8px;margin-bottom:12px}.toolbar input{width:min(460px,100%);padding:8px 10px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.toolbar button{padding:8px 10px;border:1px solid var(--line);border-radius:7px;background:var(--surface);cursor:pointer}.grid{overflow:auto;max-height:calc(100vh - 230px);background:var(--surface);border:1px solid var(--line);border-radius:8px}table{border-collapse:separate;border-spacing:0;width:max-content;min-width:100%;table-layout:fixed;font-size:13px}th,td{width:190px;max-width:320px;padding:8px 10px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);text-align:left;vertical-align:top;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}th{position:sticky;top:0;z-index:2;background:var(--surface2);font-weight:650}th:first-child,td:first-child{position:sticky;left:0;z-index:1;width:190px;background:var(--surface)}th:first-child{z-index:3;background:var(--surface2)}tr:hover td{background:#fafcfb}tr:hover td:first-child{background:#f5faf8}.wrap td{white-space:normal;overflow-wrap:anywhere}.field-type{display:block;margin-top:2px;color:var(--muted);font:500 10px/1.3 var(--mono);text-transform:uppercase}.cell{cursor:pointer}.cell:hover{color:var(--accent);text-decoration:underline}.cell a{color:var(--accent)}.cell-image{display:block;width:42px;height:48px;object-fit:cover;border-radius:5px}.state{display:inline-block;padding:2px 7px;border-radius:999px;background:var(--surface2);color:var(--muted);font-size:11px}.state.contested{background:var(--warn);color:#705700}.state.notfound{background:var(--blue);color:#315e7c}.page{max-width:1120px;margin:auto;padding:24px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.card{padding:15px;background:var(--surface);border:1px solid var(--line);border-radius:8px}.card strong{display:block;font-size:22px}.card span{color:var(--muted)}.list{margin-top:16px;background:var(--surface);border:1px solid var(--line);border-radius:8px}.item{padding:13px 15px;border-top:1px solid var(--line)}.item:first-child{border-top:0}.item p{margin:6px 0;color:#3f464c}.item a{color:var(--accent);overflow-wrap:anywhere}.item summary{cursor:pointer}.json{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface2);padding:10px;border-radius:6px;font:11px/1.5 var(--mono)}.empty{padding:28px;color:var(--muted);text-align:center}.schema{margin-top:16px}.schema details{padding:9px 0;border-top:1px solid var(--line)}dialog{width:min(760px,calc(100% - 28px));max-height:88vh;padding:0;border:1px solid var(--line);border-radius:10px;box-shadow:0 24px 80px #0004;background:var(--surface)}dialog::backdrop{background:#1118}.modal-head{position:sticky;top:0;padding:14px 16px;background:var(--surface);border-bottom:1px solid var(--line)}.modal-head button{float:right;border:0;background:transparent;cursor:pointer}.modal-body{padding:16px}.lineage{margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}blockquote{margin:8px 0;padding-left:12px;border-left:3px solid var(--accent);color:#41484d}@media(max-width:760px){.appbar{padding:14px}.snapshot{display:none}.data-layout{grid-template-columns:1fr}.table-nav{display:flex;gap:4px;overflow:auto;padding:10px;border-right:0;border-bottom:1px solid var(--line)}.table-nav .section-label{display:none}.table-nav button{width:auto;min-width:max-content}.content{padding:16px}.grid{max-height:65vh}}
</style></head><body>
<header class="appbar"><div class="brand"><div class="mark">E</div><div><h1 id="title"></h1><p id="subtitle"></p></div></div><span class="snapshot">Portable snapshot · read only</span></header>
<nav class="tabs"><button class="active" data-view="data">Data</button><button data-view="evidence">Evidence</button><button data-view="review">Review</button><button data-view="history">History</button><button data-view="about">About</button></nav>
<section id="data" class="view active"><div class="data-layout"><aside class="table-nav"><div class="section-label">Tables</div><div id="table-list"></div></aside><main class="content"><div class="content-head"><div><h2 id="table-title"></h2><span id="table-summary" class="meta"></span></div></div><div class="toolbar"><input id="table-search" type="search" placeholder="Search this table"><button id="wrap-toggle" type="button">Wrap cells</button></div><div class="grid"><table id="matrix"></table></div><div class="schema" id="schema"></div></main></div></section>
<section id="evidence" class="view"><main class="page"><div class="content-head"><h2>Evidence</h2><span id="evidence-count" class="meta"></span></div><div class="toolbar"><input id="evidence-search" type="search" placeholder="Search evidence"></div><div class="list" id="evidence-list"></div></main></section>
<section id="review" class="view"><main class="page"><h2>Review queues</h2><h3>Proposals</h3><div class="list" id="proposals"></div><h3>Question challenges</h3><div class="list" id="challenges"></div></main></section>
<section id="history" class="view"><main class="page"><div class="content-head"><h2>History</h2><span id="history-count" class="meta"></span></div><div class="toolbar"><input id="history-search" type="search" placeholder="Search events"></div><div class="list" id="event-list"></div></main></section>
<section id="about" class="view"><main class="page"><h2>Snapshot details</h2><div class="cards" id="stats"></div><div class="list" id="integrity"></div></main></section>
<dialog id="detail"><div class="modal-head"><button id="close">Close</button><strong id="detail-title"></strong></div><div class="modal-body" id="detail-body"></div></dialog>
<script>const DATA=__DATA__;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),json=v=>JSON.stringify(v,null,2),matches=(v,t)=>json(v).toLowerCase().includes(t.toLowerCase()),safeUrl=v=>/^https?:\/\//i.test(v||'')?v:null,label=q=>q.definition?.label||q.name.replaceAll('_',' ');
document.title=`${DATA.overview.project.name||'Epiq'} · data explorer`;$('title').textContent=DATA.overview.project.name||'Untitled Epiq project';$('subtitle').textContent=`${DATA.tables.reduce((n,t)=>n+t.rows.length,0)} records · ${DATA.tables.length} tables · snapshot ${DATA.generated_at||'unknown'}`;
let tableIndex=0;const lineages=[];DATA.tables.forEach(t=>t.rows.forEach(r=>Object.entries(r.cells).forEach(([q,c])=>(c.lineage||[]).forEach(l=>lineages.push({...l,entity:r.name,question:q,table:t.entity_kind})))));const evidence=[...new Map(lineages.filter(x=>x.evidence_id).map(x=>[x.evidence_id,x])).values()];
function value(c){if(c.references?.length)return c.references.map(x=>x.name);return c.state==='Answered'?(c.value??c.values):c.state==='Contested'?c.values:c.state==='NotFound'?'Not found':'Unasked'}function shown(v){return v==null?'—':Array.isArray(v)?v.join(', '):typeof v==='object'?json(v):String(v)}
function tableButtons(){$('table-list').innerHTML=DATA.tables.length?DATA.tables.map((t,i)=>`<button class="${i===tableIndex?'active':''}" data-table="${i}">${esc(t.entity_kind)}<small>${t.rows.length} rows · ${t.questions.length} fields</small></button>`).join(''):'<div class="empty">No tables</div>';document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{tableIndex=+b.dataset.table;tableButtons();renderTable()})}
function cell(t,r,q){const c=r.cells[q.name],raw=value(c),attrs=`data-kind="${esc(t.entity_kind)}" data-row="${esc(r.entity_id)}" data-question="${esc(q.name)}"`;if(c.state==='Answered'&&q.name.toUpperCase()==='URL_IMAGE'){const u=safeUrl(raw);return `<td class="cell" ${attrs}>${u?`<img class="cell-image" src="${esc(u)}" alt="${esc(r.name)}" loading="lazy" referrerpolicy="no-referrer">`:'—'}</td>`}if(c.state==='Answered'&&q.value_type==='URL'&&safeUrl(raw))return `<td class="cell" ${attrs}><a href="${esc(raw)}" target="_blank" rel="noreferrer">${esc(raw)}</a></td>`;if(c.state==='Answered')return `<td class="cell" ${attrs}>${esc(shown(raw))}</td>`;return `<td class="cell" ${attrs}><span class="state ${c.state.toLowerCase()}">${esc(shown(raw))}</span></td>`}
function renderTable(){const t=DATA.tables[tableIndex],term=$('table-search').value;if(!t){$('table-title').textContent='No data';$('matrix').innerHTML='';return}const rows=t.rows.filter(r=>matches(r,term));$('table-title').textContent=t.entity_kind;$('table-summary').textContent=`${rows.length} of ${t.rows.length} rows · ${t.questions.length} fields`;$('matrix').innerHTML=`<thead><tr><th>${esc(t.entity_kind)}</th>${t.questions.map(q=>`<th>${esc(label(q))}<span class="field-type">${esc(q.value_type)}</span></th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td title="${esc(r.name)}">${esc(r.name)}</td>${t.questions.map(q=>cell(t,r,q)).join('')}</tr>`).join('')}</tbody>`;$('schema').innerHTML=`<details><summary>Field definitions</summary>${t.questions.map(q=>`<details><summary><b>${esc(label(q))}</b> · <span class="meta">${esc(q.value_type)}</span></summary><pre class="json">${esc(json(q.definition))}</pre></details>`).join('')}</details>`;document.querySelectorAll('.cell').forEach(x=>x.onclick=e=>{if(e.target.tagName!=='A')showCell(x.dataset.kind,x.dataset.row,x.dataset.question)})}
function showCell(kind,id,name){const t=DATA.tables.find(x=>x.entity_kind===kind),r=t.rows.find(x=>x.entity_id===id),q=t.questions.find(x=>x.name===name),c=r.cells[name];$('detail-title').textContent=`${r.name} · ${label(q)}`;let out=`<p><b>${esc(c.state)}</b> · ${esc(q.value_type)}</p><pre class="json">${esc(json(value(c)))}</pre>`;if(c.research)out+=`<h3>Research outcome</h3><pre class="json">${esc(json(c.research))}</pre>`;for(const l of c.lineage||[]){const u=safeUrl(l.source?.url);out+=`<div class="lineage"><b>${esc(l.claim_id||'Claim')}</b> · ${esc(l.confidence||'')}<blockquote>${esc(l.excerpt||'')}</blockquote>${u?`<a href="${esc(u)}" target="_blank" rel="noreferrer">${esc(l.source?.title||u)}</a>`:''}<details><summary>Full record</summary><pre class="json">${esc(json(l))}</pre></details></div>`}if(!(c.lineage||[]).length)out+='<p>No claim lineage.</p>';$('detail-body').innerHTML=out;$('detail').showModal()}
function itemList(id,items,empty){$(id).innerHTML=items.length?items.map(x=>`<details class="item"><summary>${esc(x.status||x.problem||x.proposal_id||x.challenge_id||x.evidence_id||'Record')}</summary><pre class="json">${esc(json(x))}</pre></details>`).join(''):`<div class="empty">${empty}</div>`}
function renderEvidence(){const a=evidence.filter(x=>matches(x,$('evidence-search').value));$('evidence-count').textContent=`${a.length} of ${evidence.length}`;$('evidence-list').innerHTML=a.length?a.map(x=>{const u=safeUrl(x.source?.url);return `<article class="item"><b>${esc(x.source?.title||x.evidence_id)}</b><span class="meta"> · ${esc(x.table)} / ${esc(x.entity)} / ${esc(x.question)}</span><p>${esc(x.excerpt||'')}</p>${u?`<a href="${esc(u)}" target="_blank" rel="noreferrer">${esc(u)}</a>`:''}<details><summary>Full record</summary><pre class="json">${esc(json(x))}</pre></details></article>`}).join(''):'<div class="empty">No matching evidence</div>'}
function renderHistory(){const a=DATA.events.filter(x=>matches(x,$('history-search').value));$('history-count').textContent=`${a.length} of ${DATA.events.length}`;$('event-list').innerHTML=a.length?a.map(x=>`<details class="item"><summary><span class="meta">#${x.seq}</span> ${esc(x.event_type)} · ${esc(x.actor)} · ${esc(x.recorded_at)}</summary><pre class="json">${esc(json(x))}</pre></details>`).join(''):'<div class="empty">No matching events</div>'}
$('stats').innerHTML=[[DATA.tables.length,'tables'],[DATA.tables.reduce((n,t)=>n+t.rows.length,0),'records'],[evidence.length,'evidence items'],[DATA.events.length,'events']].map(x=>`<div class="card"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('');$('integrity').innerHTML=`<details class="item"><summary>${DATA.integrity.ok?'Integrity checks passed':'Review integrity findings'} · ${DATA.integrity.findings?.length||0} findings</summary><pre class="json">${esc(json(DATA.integrity))}</pre></details>`;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view],.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.view).classList.add('active')});$('table-search').oninput=renderTable;$('wrap-toggle').onclick=()=>{const on=$('matrix').classList.toggle('wrap');$('wrap-toggle').textContent=on?'Compact rows':'Wrap cells'};$('evidence-search').oninput=renderEvidence;$('history-search').oninput=renderHistory;$('close').onclick=()=>$('detail').close();itemList('proposals',DATA.review.claim_proposals,'No proposals');itemList('challenges',DATA.review.question_challenges,'No question challenges');tableButtons();renderTable();renderEvidence();renderHistory();
</script></body></html>"""


def render_ledger_html(data: dict[str, Any]) -> str:
    """Embed canonical snapshot-shaped data in the portable explorer shell."""
    encoded = json.dumps(data, separators=(",", ":"), ensure_ascii=False).replace("</", "<\\/")
    return TEMPLATE.replace("__DATA__", encoded)
